file.content:
"""한국어 음성 명령 -> 구조화 명령 (action, color, shape).

출처: MARK1 command_parser v1.2 (etc/mark1_voice_controller, 브랜치 feat/mark1-voice-controller)
ARIS3 변경 (2026-11-08, 11-09):
  - 작업 물체가 정육면체뿐이라 물체를 색으로 고른다 -> PICK 은 **색 필수, 도형 선택**
    (MARK1 은 도형 필수·색 선택이었음)
  - 노랑(yellow) 추가, '큐브/정육면체/네모/사각형' -> cube
  - Whisper 오인식 보정 표와 '지워줘'(모호) 처리는 MARK1 그대로
  - 「멈춰」(stop, 가장 먼저 봄), 「계속해」(resume: 정지로 끊긴 순서를 이어서),
    「연결해제」(disconnect), 「가동」(power_on: 접속 후 팔을 위로 일자로 펴기) - 2026-11-11
  - 지시어 「이거/그거/저거」(화면에서 고른 물체), 「저기/여기/거기」(화면에서 고른 자리).
    지금은 마우스 클릭, 이후 손짓이 가리킨 것을 쓴다. 실제 물체·자리 확인은 GUI 가 한다
  - 쌓기 (2026-11-13): 「노란 큐브를 파란 큐브 위로 옮겨줘」 -> pick, color=yellow, target_color=blue.
    「위」 바로 앞에 나온 색이 받침, 다른 색이 집을 큐브 (「파란 큐브 위에 노란 큐브 올려」 도 같은 뜻).
    「이거 파란 큐브 위에 올려」 -> 화면에서 고른 물체를 파랑 위로

ROS 에 의존하지 않는 순수 함수라서 단위 시험(test/test_command_parser.py)에서 바로 쓴다.
"""

# Whisper 오인식 보정 (MARK1 실측에서 발견된 표현)
CORRECTIONS = {
    "3각형": "삼각형",
    "사닷형": "사각형",
    "바란색": "파란색",
    "허록색": "초록색",
    "크록색": "초록색",
    "지버죠": "집어줘",
    "지버줘": "집어줘",
    "지버조": "집어줘",
    "지보죠": "집어줘",
    "돌려나": "돌려놔",
    # ARIS3 실물 마이크 실측 (2026-11-09)
    "나와줘": "놔줘",
    "피우그": "큐브",
    "고른타리": "고른자리",
    "노키": "놓기",
    "배려나": "내려놔",
    "내려나": "내려놔",
    "내려와": "내려놔",
}

COLOR_WORDS = {
    "red": ["빨간색", "빨간", "빨강", "붉은색", "붉은", "진빨강"],
    "blue": ["파란색", "파란", "파랑", "푸른색", "푸른", "진파랑"],
    "green": ["초록색", "초록", "녹색", "진초록", "연초록"],
    "yellow": ["노란색", "노란", "노랑", "누런", "샛노란"],
}

SHAPE_WORDS = {
    "cube": ["정육면체", "큐브", "블록", "상자", "네모", "사각형"],
    "triangle": ["삼각형", "세모"],
    "circle": ["동그라미", "원형", "원모양"],
}

PLACE_WORDS = ["내려놔", "내려놓", "놓아줘", "놔줘", "놔", "놓으", "놓기", "돌려놔", "돌려놓", "원래대로"]

# 지시어: 화면에서 (지금은 마우스 클릭, 이후 손짓으로) 고른 물체·자리를 가리킨다 (2026-11-09)
OBJECT_DEIXIS = ["이거", "이것", "이걸", "그거", "그것", "그걸", "저거", "저것", "저걸"]
PLACE_DEIXIS = ["저기", "여기", "거기", "그자리", "이자리", "저자리", "그곳", "이곳", "저곳",
                "고른자리", "고른곳"]   # GUI 버튼 이름 「고른 자리에 놓기」 (2026-11-09)
PICK_WORDS = ["집어", "집으", "집고", "잡아", "잡으", "잡고", "들어", "옮겨"]
# 홈 자세로 (2026-11-09): 「집으로 돌아가」 의 「집으」 가 PICK 으로 읽히지 않게 PICK 보다 먼저 본다
HOME_WORDS = ["집으로돌아", "집으로가", "집으로복귀", "홈으로", "홈위치", "원위치", "복귀"]
# 정지·이어서 (2026-11-11): 「멈춰」 는 무엇보다 먼저 본다 (「멈춰 그거 잡지 마」 도 정지)
# 「멈쳐」 「먹쳐」: Whisper 가 실제로 「멈춰」 를 이렇게 적음 (2026-11-11). 정지는 넓게 받는 쪽이 안전
STOP_WORDS = ["멈춰", "멈춰라", "멈추", "멈춤", "멈쳐", "멈처", "먹쳐", "정지", "그만", "스톱", "stop"]
RESUME_WORDS = ["계속해", "계속하", "계속진행", "이어서", "이어해", "다시진행"]
# 접속 (2026-11-11): 「연결해제」 가 「연결해」 를 품고 있으므로 끊기를 먼저 본다
DISCONNECT_WORDS = ["연결해제", "연결끊", "연결을끊", "접속해제", "접속끊", "접속을끊", "전원꺼", "꺼져"]
POWER_ON_WORDS = ["가동", "기동", "작동시작", "깨어나", "일어나"]
# 그리퍼 열기 (2026-11-14): 「그리퍼 열어」「손 펴」「집게 벌려」. 「열어」 만으로는 받지 않는다 (잡담에 흔한 말 -
# 들고 있는 큐브를 떨어뜨릴 수 있으니 그리퍼·손·집게 + 열/펴/벌 이 함께 있을 때만)
GRIPPER_NOUNS = ["그리퍼", "그립퍼", "그리파", "손", "집게"]
OPEN_VERBS = ["열어", "열기", "열어줘", "열자", "펴", "펼쳐", "벌려"]
# 쌓기 (2026-11-13): 「~ 위에/위로」 또는 「올려/쌓아」 가 있고 색이 둘이면 한 큐브를 다른 큐브 위에 놓는다
STACK_WORDS = ["위에", "위로", "위쪽", "올려", "올리", "쌓아", "쌓기", "쌓으"]


def normalize_text(text):
    """공백을 없애고 알려진 오인식을 바로잡는다."""
    text = "".join(text.split())
    for wrong, right in CORRECTIONS.items():
        text = text.replace(wrong, right)
    return text


def _first_match(text, table):
    for key, words in table.items():
        if any(w in text for w in words):
            return key
    return ""


def _colors_in_order(norm):
    """문장에 나온 색을 나온 순서대로 [(위치, 색, 그 색 낱말 끝 위치)]. 같은 색은 처음 한 번만."""
    found = []
    for key, words in COLOR_WORDS.items():
        hits = [(norm.find(w), len(w)) for w in words if w in norm]
        if hits:
            pos, n = min(hits)
            found.append((pos, key, pos + n))
    return sorted(found)


def stack_colors(norm):
    """쌓기 문장이면 (집을 색, 받침 색), 아니면 None. 집을 색이 ""면 「이거」(화면에서 고른 물체).

    「위」 가 바로 뒤따르는 색이 받침이다: 「노란 큐브를 파란 큐브 위로」, 「파란 큐브 위에 노란 거 올려」.
    「위」 가 없으면(「노랑을 파랑에 쌓아」) 먼저 말한 색이 집을 큐브다.
    """
    if not any(w in norm for w in STACK_WORDS):
        return None
    cols = _colors_in_order(norm)
    if not cols:
        return None
    segs = []                                   # 각 색 낱말 뒤 ~ 다음 색 앞
    for i, (_pos, key, end) in enumerate(cols):
        nxt = cols[i + 1][0] if i + 1 < len(cols) else len(norm)
        segs.append((key, norm[end:nxt]))
    under = [k for k, seg in segs if seg[:8].find("위") >= 0]
    if len(cols) == 1:                          # 「이거 파란 큐브 위에 올려」
        if under and any(w in norm for w in OBJECT_DEIXIS):
            return "", under[0]
        return None
    base = under[0] if under else cols[1][1]
    obj = next(k for _p, k, _e in cols if k != base)
    return obj, base


def parse_command(text):
    """문장 -> {action, color, shape, target_color, ambiguous, ref_object, ref_place, original_text, normalized_text}."""
    cmd = _parse(text)
    cmd["target_color"] = ""
    if cmd["action"] in ("pick", "place", ""):
        st = stack_colors(cmd["normalized_text"])
        if st is not None:                      # 쌓기: 집어서 받침 큐브 위에 놓기 (자리는 화면 클릭 대신 받침 큐브)
            cmd.update(action="pick", color=st[0], target_color=st[1], ambiguous=False,
                       ref_object=not st[0], ref_place=False)
    return cmd


def _parse(text):
    """문장 -> {action, color, shape, ambiguous, original_text, normalized_text} (쌓기 전 기본 해석)."""
    norm = normalize_text(text)
    color = _first_match(norm, COLOR_WORDS)
    shape = _first_match(norm, SHAPE_WORDS)
    ref_object = any(w in norm for w in OBJECT_DEIXIS)
    ref_place = any(w in norm for w in PLACE_DEIXIS)
    if ref_place and not color:
        # 「저기로 옮겨줘」: 무엇을 말하지 않고 자리만 말하면 화면에서 고른 물체를 옮긴다
        ref_object = True
    action = ""
    ambiguous = False
    low = norm.lower()
    if any(w in low for w in STOP_WORDS):
        return {"action": "stop", "color": "", "shape": "", "ambiguous": False,
                "ref_object": False, "ref_place": False, "original_text": text, "normalized_text": norm}
    simple = {"action": "", "color": "", "shape": "", "ambiguous": False,
              "ref_object": False, "ref_place": False, "original_text": text, "normalized_text": norm}
    if any(w in norm for w in DISCONNECT_WORDS):
        return dict(simple, action="disconnect")
    if any(w in norm for w in POWER_ON_WORDS):
        return dict(simple, action="power_on")
    if any(n in norm for n in GRIPPER_NOUNS) and any(v in norm for v in OPEN_VERBS):
        return dict(simple, action="gripper_open")
    if any(w in norm for w in RESUME_WORDS):
        return {"action": "resume", "color": "", "shape": "", "ambiguous": False,
                "ref_object": False, "ref_place": False, "original_text": text, "normalized_text": norm}
    if any(w in norm for w in HOME_WORDS):
        # 「집으로 돌아가」「홈으로 가」「원위치」: 물체·자리 말과 상관없이 홈 자세로
        return {"action": "home", "color": "", "shape": "", "ambiguous": False,
                "ref_object": False, "ref_place": False, "original_text": text, "normalized_text": norm}
    if ref_place and (color or ref_object):
        # 「이거 저기로 옮겨줘」「파란 거 저기 놔줘」: 물체와 자리가 다 있으면 옮기기(pick -> place)
        action = "pick"
    elif any(w in norm for w in PLACE_WORDS):      # PLACE 를 먼저 본다 ("들어"보다 "내려놔" 우선)
        action = "place"
    elif any(w in norm for w in PICK_WORDS):
        action = "pick"
    elif "지워줘" in norm and (color or shape or ref_object):
        # '집어줘' 의 오인식일 수도, 진짜 '지워줘' 일 수도 있다 -> 자동으로 정하지 않는다
        ambiguous = True
    return {"action": action, "color": color, "shape": shape, "ambiguous": ambiguous,
            "ref_object": ref_object, "ref_place": ref_place,
            "original_text": text, "normalized_text": norm}


def validate_command(cmd, known_colors=None):
    """(실행 가능한가, 이유). known_colors 를 주면 그 안의 색만 허용한다."""
    if cmd["ambiguous"]:
        return False, "모호한 명령입니다. 다시 말씀해 주세요."
    if cmd["action"] == "pick" and cmd.get("target_color"):
        if cmd["target_color"] == cmd["color"]:
            return False, "같은 색 큐브 위에 쌓으라는 명령입니다. 받침 큐브의 색을 다시 말씀해 주세요."
        if known_colors is not None and cmd["target_color"] not in known_colors:
            return False, f"작업 공간에 없는 색입니다: {cmd['target_color']}"
        if not cmd["color"] and not cmd.get("ref_object"):
            return False, "쌓을 물체의 색이 지정되지 않았습니다."
        what = cmd["color"] or "화면에서 고른 물체"
        return True, f"STACK 명령 생성 ({what} -> {cmd['target_color']} 위)"
    if cmd["action"] == "pick":
        if cmd.get("ref_object") and not cmd["color"]:
            return True, "PICK 명령 생성 (화면에서 고른 물체" + (" -> 화면에서 고른 자리)" if cmd.get("ref_place") else ")")
        if not cmd["color"]:
            return False, "집을 물체의 색이 지정되지 않았습니다. (「이거」 라고 하려면 화면에서 먼저 고르세요)"
        if known_colors is not None and cmd["color"] not in known_colors:
            return False, f"작업 공간에 없는 색입니다: {cmd['color']}"
        return True, "PICK 명령 생성" + (" (화면에서 고른 자리로)" if cmd.get("ref_place") else "")
    if cmd["action"] == "place":
        return True, "PLACE 명령 생성 (집었던 자리에 놓기)"
    if cmd["action"] == "home":
        return True, "HOME 명령 생성 (홈 자세로 돌아가기)"
    if cmd["action"] == "stop":
        return True, "STOP 명령 생성 (정지)"
    if cmd["action"] == "disconnect":
        return True, "DISCONNECT 명령 생성 (로봇 접속 끊기)"
    if cmd["action"] == "power_on":
        return True, "POWER_ON 명령 생성 (접속 -> 팔을 일자로 펴기)"
    if cmd["action"] == "resume":
        return True, "RESUME 명령 생성 (멈춘 단계부터 이어서)"
    if cmd["action"] == "gripper_open":
        return True, "GRIPPER_OPEN 명령 생성 (그리퍼 열기)"
    return False, "지원하지 않는 명령입니다."

content.content:
void MainWindow::stackRun(const QString & heard, const std::array<double, 2> & base_px, const std::string & base_name)
{
  if (!armOk("쌓기")) {return;}
  const auto t = pickTarget("쌓기");
  const auto xy = real_->toRobot(base_px[0], base_px[1]);
  if (!t || !xy) {return;}
  if (ask(QStringLiteral("쌓기"), heard + QStringLiteral("\n\n%1 을(를) 로봇 X %2, Y %3 mm 에서 집어\n"
      "%4 (X %5, Y %6 mm) 위에 올립니다. 놓는 높이는 큐브 한 개만큼 높습니다. (잡지 못하면 옮기지 않음)\n\n"
      "로봇 주변(손 포함)이 비었습니까?")
      .arg(QString::fromStdString(pick_name_)).arg((*t)[0], 0, 'f', 0).arg((*t)[1], 0, 'f', 0)
      .arg(QString::fromStdString(base_name)).arg((*xy)[0], 0, 'f', 0).arg((*xy)[1], 0, 'f', 0)))
  {
    real_->pickPlace(PP::PICK_AND_STACK, "쌓기", pick_name_, pick_px_, base_px);
  }
}

// ======================================================================== 실물 음성 (매번 확인창)
void MainWindow::realVoice(const aris3_interfaces::msg::VoiceCommand & v, bool allow_search)
{
  if (v.action == "stop") {                          // 「멈춰」 는 언제나 (보통은 받는 즉시 이미 처리됨)
    onStop();
    return;
  }
  if (real_->pickRunning() || dialog_open_ || search_) {
    node_->log("WARN", "음성 「" + v.text + "」 무시: 이전 순서 진행 중이거나 확인창이 떠 있음");
    node_->say("지금은 다른 작업을 하고 있어요.");
    return;
  }
  const QString heard = QStringLiteral("음성: 「%1」").arg(QString::fromStdString(v.text));
  // ARIS 목소리 (2026-11-11): 실행하면 「네, 노란색 큐브를 잡습니다.」, 못 하면 그 이유를 말한다.
  // 움직이는 명령은 아래 동작 함수가 하는 검사(조작 허용·준비·보정·놓을 자리)를 먼저 해 보고 대답을 고른다.
  const auto refuse = [&](bool need_calib, bool need_place) -> std::string {
      if (!chk_arm_->isChecked()) {return "조작 허용을 먼저 켜 주세요.";}
      if (!whyNotReady().isEmpty()) {return "아직 움직일 준비가 되지 않았어요.";}
      if (need_calib && !real_->calibReady()) {return "카메라 보정이 아직 없어요.";}
      if (need_place && !place_px_) {return "놓을 자리를 화면에서 먼저 골라 주세요.";}
      return std::string();
    };
  const auto answer = [&](const std::string & why_not) {
      node_->say(why_not.empty() ? voiceReply(v.action, v.color, v.shape, v.refers_selected_place) : why_not);
    };
  // 음성으로 시작한 동작은 확인창 없이 바로 실행한다 (사용자 결정 2026-11-11).
  // 조작 허용 확인(armOk)과 정지는 그대로 동작한다. 이 함수를 벗어나면 다시 묻는다 (손짓·버튼은 계속 확인창).
  struct DirectGuard {
    bool & f;
    explicit DirectGuard(bool & flag) : f(flag) {f = true;}
    ~DirectGuard() {f = false;}
  } direct(voice_direct_);
  if (v.action == "disconnect") {                   // 「아리스 연결해제」: 접속 끊기 (서보 꺼짐, 브레이크)
    power_on_until_.reset();
    answer("");
....
    homeVoice(heard);
    return;
  }
  // 말한 색(집을 큐브·받침 큐브)이 카메라에 하나도 없으면: 로봇 팔에 가렸을 수 있으니 팔을 좌우로 돌려 찾는다.
  if (v.action == "pick" && allow_search) {
    std::vector<std::string> seen;
    for (const auto & o : node_->snapshot().px_objects) {seen.push_back(o.color);}
    const auto missing = missingColors({v.color, v.target_color}, seen);
    if (!missing.empty() && node_->statusFlags().px_detections) {
      const auto why = refuse(true, false);
      if (!why.empty()) {
        node_->say(why);
        return;
      }
      std::string names;
      for (const auto & c : missing) {
        names += (names.empty() ? "" : ", ") + objectKo(c, "cube");
      }
      const auto last = objectKo(missing.back(), "cube");
      node_->say(names + josa(last, "이", "가") + " 안 보여서 팔을 옆으로 움직여 찾아볼게요.");
      node_->log("INFO", "색 탐색 시작: " + names + " 이(가) 안 보임 - J1 을 좌우로 천천히 돌리며 찾습니다 (정지하면 그만)");
      ColorSearch S;
      S.v = v;
      S.colors = missing;
      S.settle = std::chrono::steady_clock::now();
      S.deadline = S.settle + std::chrono::seconds(90);
      search_ = S;
      return;
    }
  }
  // 그 색 큐브가 카메라에 꼭 하나 보이면 그 검출. 없거나 여럿이면 이유를 말하고 nullopt (쌓기·색 집기 공용)
  const auto onlyOne = [&](const std::string & color, bool is_base)
    -> std::optional<aris3_interfaces::msg::DetectedObject> {
      std::vector<aris3_interfaces::msg::DetectedObject> same;
      for (const auto & o : node_->snapshot().px_objects) {
        if (o.color == color) {same.push_back(o);}
      }
      const auto name = objectKo(color, is_base ? "cube" : v.shape);
      if (same.empty()) {
        node_->log("WARN", "음성: 카메라에 " + color + " 큐브가 보이지 않음");
        node_->say("카메라에 " + name + josa(name, "이", "가") + " 보이지 않아요.");
        return std::nullopt;
      }
      if (same.size() > 1) {
        node_->log("WARN", "음성: " + color + " 큐브가 " + std::to_string(same.size()) + "개" +
          (is_base ? std::string(" - 어느 큐브 위에 올릴지 모름") : std::string(" - 화면에서 클릭한 뒤 「아리스 이거 …」")));
        node_->say(is_base ? name + josa(name, "이", "가") + " 여러 개라 어느 위에 올릴지 모르겠어요." :
          name + josa(name, "이", "가") + " 여러 개 있어요. 화면에서 하나를 골라 주세요.");
        return std::nullopt;
      }
      return same[0];
    };
  if (!v.target_color.empty()) {                     // 쌓기 (2026-11-13): 「노란 큐브를 파란 큐브 위로 옮겨줘」
    if (!v.color.empty()) {                          // 집을 큐브: 말한 색, 아니면 화면에서 고른 큐브(「이거」)
      const auto o = onlyOne(v.color, false);
      if (!o) {return;}
      pick_px_ = std::array<double, 2>{o->pose.pose.position.x, o->pose.pose.position.y};
      pick_name_ = o->id.empty() ? o->color : o->id;
      updatePickLabel();
    } else if (!pick_px_) {
      node_->say("어떤 물체인지 화면에서 먼저 골라 주세요.");
      return;
    }
    const auto base = onlyOne(v.target_color, true);
    if (!base) {return;}
    const std::array<double, 2> base_px{base->pose.pose.position.x, base->pose.pose.position.y};
    if (std::hypot((*pick_px_)[0] - base_px[0], (*pick_px_)[1] - base_px[1]) < 20.0) {
      node_->log("WARN", "쌓기: 집을 큐브와 받침 큐브가 같음");
      node_->say("올릴 물체와 받침 큐브가 같아요.");
      return;
    }
    const auto why = refuse(true, false);
    node_->say(why.empty() ? voiceReply("pick", v.color, v.shape, false, v.target_color) : why);
    stackRun(heard, base_px, base->id.empty() ? base->color : base->id);
    return;
  }
  if (v.refers_selected_place && v.color.empty() && real_->holding().value_or(false)) {
    const auto why = refuse(true, true);
    node_->say(why.empty() ? voiceReply("place", "", "", true) : why);
    placeSelected(heard);                            // 들고 있을 때 「저기 놔줘」 = 고른 자리에 놓기
    return;
  }
  if (v.action == "place") {
    const auto why = refuse(true, false);
    node_->say(why.empty() ? voiceReply("place", "", "", false) : why);
    placeHere(heard);
    return;
  }
  if (!v.color.empty()) {                            // 「빨간 큐브 집어줘」: 그 색 검출이 하나일 때만
    const auto o = onlyOne(v.color, false);
    if (!o) {return;}
    pick_px_ = std::array<double, 2>{o->pose.pose.position.x, o->pose.pose.position.y};
    pick_name_ = o->id.empty() ? o->color : o->id;
    updatePickLabel();
  } else if (!pick_px_) {                            // 「이거 집어줘」
    node_->log("WARN", "「이거」 가 무엇인지 모름 - 먼저 카메라 화면에서 큐브를 클릭하거나 가리키세요");
    node_->say("어떤 물체인지 화면에서 먼저 골라 주세요.");
    return;
  }
  answer(refuse(true, v.refers_selected_place));
  if (v.refers_selected_place) {                     // 「이거 저기로 옮겨줘」: 집어서 고른 자리에 놓기
    pickAndPlace(heard);
  } else {
    pickRun(heard);
  }
}

