  if ((b[0] & 0xF0) != 0xE0) {return without;}
  const unsigned cp = ((b[0] & 0x0Fu) << 12) | ((b[1] & 0x3Fu) << 6) | (b[2] & 0x3Fu);
  if (cp < 0xAC00 || cp > 0xD7A3) {return without;}
  return (cp - 0xAC00) % 28 != 0 ? with_final : without;    // 28 = 받침 종류 수 (0 = 받침 없음)
}

